const SETTINGS_KEY='fresh-order-settings-v2';
let preferences=OrderPolicy.defaults(),orderPatch=null,orderRequest='',requestDirty=false,policyResult=null,policyCache='',settingsDraft=null,settingsTab='profile',policySelection=null,settingsOwnerDirty=false;
try{const saved=JSON.parse(localStorage.getItem(SETTINGS_KEY)||'null');if(saved?.version===1){preferences={...preferences,...saved,preferences:{...preferences.preferences,...saved.preferences},scenario:{...preferences.scenario,...saved.scenario},constraints:{...preferences.constraints,...saved.constraints}};}}catch{console.warn('설정을 읽지 못해 기본값을 사용합니다.');}
const policyFields=[
 ['service_level','서비스 수준',.5,.9999,.001,'안전재고 계산 기준입니다. 실제 품절 확률과 다릅니다.','preferences'],
 ['extra_demand_buffer_ratio','추가 수요 여유율',0,.5,.01,'0.1은 커버 구간 수요의 10%를 추가 확보합니다.','preferences'],
 ['shortage_weight','품절 손실 가중치',0,10,.1,'놓치는 매출을 얼마나 중요하게 볼지 정합니다.','preferences'],
 ['waste_weight','폐기 비용 가중치',0,10,.1,'사용기한 경과 재료비의 중요도입니다.','preferences'],
 ['tail_weight','큰 손실 대비 비중',0,1,.05,'평균 손실과 나쁜 상황의 손실을 혼합합니다.','preferences'],
 ['cvar_alpha','CVaR 기준',.5,.99,.01,'0.9는 손실이 큰 쪽 10%의 평균을 사용합니다.','preferences'],
 ['demand_multiplier','전체 수요 배율',.1,3,.05,'행사 반영 후 전체 수요에 적용합니다.','scenario'],
 ['delay_buffer_days','기존 입고 예정 지연일',0,7,1,'기존 미입고 물량에만 적용하며 신규 배송일은 바꾸지 않습니다.','scenario']
];
const effectivePolicy=()=>OrderPolicy.merge(preferences,orderPatch);
function policyProjection(){return PromotionEngine.project(PROMO,state.date,state.store,forecastWindow().dates,getPromotionPlans());}
function calculatePolicy(){const projected=policyProjection(),policy=effectivePolicy(),key=JSON.stringify([activeSnapshot,state.store,state.date,projected,policy]);if(key!==policyCache){policyResult=OrderPolicy.evaluate(activeSnapshot,{asOf:state.date,storeId:state.store,suppliers:DATA.suppliers,dates:forecastWindow().dates,baseIngredients:PromotionEngine.project(PROMO,state.date,state.store,forecastWindow().dates,[]).ingredients},projected,PROMO,policy);policyCache=key;policySelection=null;}return policyResult;}
async function extractRequest(text,api){const response=await fetch('/api/policy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,api})});if(!response.ok){let msg;try{msg=(await response.json()).error}catch{}throw Error(msg||'자연어'+' 해석 서버가 없습니다. python3 web-dashboard/serve.py로 실행해주세요.');}const result=await response.json();if(result.status!=='ready')throw Error(result.issues.join('\n'));return result;}
function auditHTML(patch){const entries=patch.audit.filter(x=>!x.mapping);return entries.length?`<div class="policy-chips">${entries.map(a=>`<span>${safeText(fieldName(a.field))}: <b>${safeText(formatPolicyValue(a.after))}</b></span>`).join('')}</div>`:'<p>기본 설정을 그대로 사용합니다.</p>';}
const fieldName=k=>policyFields.find(f=>f[0]===k)?.[1]||({mode:'성향',budget:'예산',max_stockout_probability:'품절 확률 상한',max_expected_waste_won:'폐기비 상한',store_ids:'적용 매장',excluded_ingredient_ids:'발주 제외',allow_emergency:'긴급발주 허용'}[k]||k);
function formatPolicyValue(v){if(v===null)return '제한 없음';if(typeof v==='object')return Array.isArray(v)?v.join(', '):n(v.won)+'원 '+(v.operator==='lt'?'미만':'이하');return ({balanced:'균형',safe:'품절 대비',lean:'재고 절약',true:'허용',false:'불가'})[String(v)]||String(v);}
function renderPolicyHome(){
 let root=$('#quickOrder');if(!root){root=document.createElement('section');root.id='quickOrder';root.className='quick-order';$('.page-heading').after(root);}root.hidden=state.nav!=='overview';
 const r=policyResult,best=r?.best,chosen=r?.candidates.find(c=>c.name===policySelection)||best,ready=!!activeSnapshot&&hasForecast();
 root.innerHTML=`<div class="quick-top"><div><span class="eyebrow">오늘의 발주</span><h2>${chosen&&ready?money(Object.keys(state.overrides).length&&DRAFT?DRAFT.totals.purchase_amount:chosen.purchase):'발주 준비'}</h2><p>${ready?(chosen?'설정과 이번 요청을 반영한 추천안':'현재 조건을 충족하는 후보가 없습니다.'):'재고 기준일과 마감 기록을 확인하세요.'}</p></div><div class="quick-actions"><button id="openSettings" class="button secondary">⚙ 설정</button><button id="optimalOrder" class="button primary" ${!ready||!chosen||requestDirty?'disabled':''}>${Object.keys(state.overrides).length?'수정한 안으로 주문':policySelection?'선택한 안으로 주문':'최적의 안으로 주문'} →</button></div></div><div class="request-box"><label for="orderRequest">이번 주문 요청 <span>선택 · 기본 설정은 유지됩니다</span></label><div class="request-input"><textarea id="orderRequest" rows="2" maxlength="2000" placeholder="예: 이번에는 30만원 이하, 10% 여유, 우유 제외">${safeText(orderRequest)}</textarea><button id="applyOrderRequest" class="button secondary">요청 반영</button></div><div id="requestStatus" role="status">${requestDirty?'<span class="expiry-warn">입력한 요청을 반영해주세요.</span>':orderPatch?auditHTML(orderPatch)+'<button id="clearOrderRequest" class="text-action">이번 요청 해제</button>':'기본 발주 기준을 사용합니다.'}</div></div><div class="quick-bottom"><button id="showPolicy" class="text-action">적용 기준 보기 ↗</button><small>비교한 후보 중 추천 · 최종 확인 후 CSV 저장</small></div>`;
 $('#openSettings').onclick=()=>openSettings();$('#optimalOrder').onclick=()=>reviewOrders();
 $('#orderRequest').oninput=e=>{orderRequest=e.target.value;requestDirty=true;$('#optimalOrder').disabled=true;$('#reviewBtn').disabled=true;$('#requestStatus').textContent='입력한 요청을 반영해주세요. 빈칸으로 반영하면 이번 요청이 해제됩니다.';};
 $('#applyOrderRequest').onclick=async()=>{const button=$('#applyOrderRequest');button.disabled=true;button.textContent='해석 중…';try{const text=orderRequest.trim();const patch=text?await extractRequest(text,preferences.api):null;if(patch?.audit.some(a=>a.field==='store_ids'&&a.after.length>1))throw Error('이번 요청은 한 매장씩 적용해주세요. 여러 매장 합산 발주는 지원하지 않습니다.');orderPatch=patch;requestDirty=false;state.overrides={};policyCache='';render();toast(text?'이번 요청을 반영했습니다.':'기본 설정으로 되돌렸습니다.');}catch(e){$('#requestStatus').textContent=e.message;}finally{button.disabled=false;button.textContent='요청 반영';}};
 if($('#clearOrderRequest'))$('#clearOrderRequest').onclick=()=>{orderPatch=null;orderRequest='';requestDirty=false;state.overrides={};policyCache='';render();};
 $('#showPolicy').onclick=()=>{const p=effectivePolicy();showDrawer(`<div class="drawer-header"><h2>이번 발주 기준</h2><button class="icon-button close-drawer">×</button></div><p>이번 요청에서 바꾼 항목만 기본 설정에 우선 적용합니다.</p>${policyFields.map(f=>`<div class="calc-line">${f[1]}<b>${p[f[6]][f[0]]}</b></div>`).join('')}<div class="calc-line">예산<b>${formatPolicyValue(p.constraints.budget)}</b></div><p>제외 품목: ${safeText(p.constraints.excluded_ingredient_ids.join(', ')||'없음')}</p>${orderPatch?auditHTML(orderPatch):''}<div class="explanation">연결된 팀 평가 엔진과 과거 예측 오차 시나리오 ${ENGINE_PARAMS.scenarios.n}개를 사용합니다. 품절은 다음 보충 전까지, 폐기는 7일 범위입니다. 시나리오 확률은 현실의 확률을 보장하지 않습니다. 긴급발주는 생성하지 않습니다. 비교 후보 밖의 최적해는 탐색하지 않습니다.</div>`);};
}
function renderPolicyPlans(){const r=policyResult;if(!r)return;const selected=r.candidates.find(c=>c.name===policySelection)||r.best;
 $('#orderPlanCards').innerHTML=`<details class="alternative-plans"><summary>다른 발주안 비교 <span>${r.candidates.length}개 후보</span></summary><div class="comparison-grid">${r.candidates.map(c=>`<button class="comparison-card ${c.name===selected?.name?'is-selected':''}" data-candidate="${safeText(c.name)}" ${!c.feasible?'disabled':''}><b>${safeText(c.name)} ${c===r.best?'· 추천':''}</b><strong>${money(c.purchase)}</strong><small>부족 시나리오 ${n(c.prob*100,1)}% · 폐기 ${money(c.waste)}</small><small>손실매출 ${money(c.lost)} · 비교 점수 ${n(c.score)}</small>${c.violations.length?`<small class="expiry-warn">${safeText(c.violations.join(' · '))}</small>`:''}</button>`).join('')}</div><p class="entry-storage-note">팀 평가 엔진 · 과거 오차 시나리오 ${ENGINE_PARAMS.scenarios.n}개. 모든 후보에 같은 품절·폐기 가중치와 CVaR 기준을 적용합니다. 비교 점수가 작을수록 현재 설정에 맞는 안입니다.</p></details>`;
 $$('[data-candidate]').forEach(b=>b.onclick=()=>{policySelection=b.dataset.candidate;state.overrides={};render();});
}
function openSettings(){settingsDraft=JSON.parse(JSON.stringify(preferences));settingsTab='profile';settingsOwnerDirty=false;let dialog=$('#settingsDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='settingsDialog';dialog.className='settings-dialog';document.body.append(dialog);}renderSettings();dialog.showModal();}
function settingsInput(f){const [key,label,min,max,step,help,group]=f;return `<label class="setting-field">${label}<input data-setting="${group}.${key}" type="number" min="${min}" max="${max}" step="any" value="${settingsDraft[group][key]}" required><small>${help} (${min}–${max})</small></label>`;}
function collectSettings(){for(const el of $$('[data-setting]')){const path=el.dataset.setting.split('.'),target=path.length===2?settingsDraft[path[0]]:settingsDraft,key=path.at(-1);if(el.type==='checkbox')target[key]=el.checked;else if(el.type==='number'){if(!el.checkValidity()||el.value==='')throw Error('입력값 범위를 확인해주세요.');target[key]=Number(el.value);}else target[key]=el.value;}if($('#settingBudget')){const value=$('#settingBudget').value;if(value!==''&&(!$('#settingBudget').checkValidity()||!Number.isFinite(+value)))throw Error('예산을 확인해주세요.');settingsDraft.constraints.budget=value===''?null:{won:+value,operator:$('#budgetOperator').value};for(const [id,k,scale] of [['settingProbability','max_stockout_probability',100],['settingWaste','max_expected_waste_won',1]]){const e=$('#'+id);if(e.value!==''&&!e.checkValidity())throw Error('상한 범위를 확인해주세요.');settingsDraft.constraints[k]=e.value===''?null:Number(e.value)/scale;}settingsDraft.constraints.excluded_ingredient_ids=$$('[data-exclude]:checked').map(e=>e.dataset.exclude);settingsDraft.constraints.store_ids=$$('[data-scope]:checked').map(e=>e.dataset.scope);if(!settingsDraft.constraints.store_ids.length)throw Error('매장을 하나 이상 선택해주세요.');}}
function renderSettings(){const d=settingsDraft;$('#settingsDialog').innerHTML=`<form id="settingsForm"><div class="settings-header"><div><small>매장 운영</small><h2>설정</h2></div><button type="button" id="closeSettings" class="icon-button" aria-label="닫기">×</button></div><div class="settings-layout"><nav class="settings-tabs" aria-label="설정 항목">${[['profile','기본 성향'],['parameters','발주 기준'],['constraints','한도·제외 품목'],['storage','화면·저장']].map(([key,label])=>`<button type="button" data-settings-tab="${key}" class="${settingsTab===key?'active':''}">${label}</button>`).join('')}</nav><div class="settings-content">${settingsTab==='profile'?`<h3>기본 성향</h3><p>평소 발주 기준을 적고, 반영되는 값을 확인하세요.</p><label class="setting-field">평소 요청<textarea id="ownerText" data-setting="ownerText" rows="3" maxlength="2000" placeholder="예: 품절을 막고 싶어. 30만원 이하로 주문해줘.">${safeText(d.ownerText)}</textarea></label><label class="setting-check"><input type="checkbox" data-setting="api" ${d.api?'checked':''}> 자유 문장 해석 사용</label><small>끄면 한정된 문법을 사용합니다. 켜려면 서버 API 환경변수가 필요합니다. 문장과 매장·식자재 이름이 설정한 제공사에 전달됩니다.</small><button type="button" id="interpretOwner" class="button secondary">문장으로 기준 채우기</button><div id="ownerPreview"></div><h3>빠른 선택</h3><div class="preset-buttons">${[['balanced','균형'],['safe','품절 대비'],['lean','재고 절약']].map(([key,label])=>`<button type="button" data-preset="${key}" class="button ${d.mode===key?'primary':'secondary'}">${label}</button>`).join('')}</div><p class="entry-storage-note">빠른 선택은 성향 관련 6개 값만 바꿉니다. 예산과 제외 품목은 유지합니다. 세부 값은 발주 기준에서 직접 바꿀 수 있습니다.</p><div class="policy-chips"><span>서비스 수준 <b>${n(d.preferences.service_level*100,2)}%</b></span><span>품절 : 폐기 <b>${d.preferences.shortage_weight} : ${d.preferences.waste_weight}</b></span><span>큰 손실 비중 <b>${n(d.preferences.tail_weight*100)}%</b></span></div>`:settingsTab==='parameters'?`<h3>발주 기준</h3><div class="settings-fields">${policyFields.map(settingsInput).join('')}</div><p class="entry-storage-note">이 값은 후보 수량·수요·입고일·손실 점수에 반영됩니다. 공급사의 발주일·최소금액·포장 단위는 원본 데이터를 따릅니다.</p>`:settingsTab==='constraints'?`<h3>발주 한도</h3><div class="settings-fields"><label class="setting-field">예산 (원)<input id="settingBudget" type="number" min="0" max="1000000000000" step="1" value="${d.constraints.budget?.won??''}" placeholder="제한 없음"><select id="budgetOperator"><option value="le">이하</option><option value="lt" ${d.constraints.budget?.operator==='lt'?'selected':''}>미만</option></select></label><label class="setting-field">부족 시나리오 비율 상한 (%)<input id="settingProbability" type="number" min="0" max="100" step="any" value="${d.constraints.max_stockout_probability===null?'':d.constraints.max_stockout_probability*100}" placeholder="제한 없음"><small>7일 중 한 품목 이상 부족한 합성 시나리오의 비율입니다.</small></label><label class="setting-field">기대 폐기비 상한 (원)<input id="settingWaste" type="number" min="0" max="1000000000000" step="1" value="${d.constraints.max_expected_waste_won??''}" placeholder="제한 없음"></label></div><h3>적용 매장</h3><div class="checkbox-grid">${DATA.stores.map(s=>`<label><input type="checkbox" data-scope="${s.store_id}" ${!d.constraints.store_ids||d.constraints.store_ids.includes(s.store_id)?'checked':''}> ${safeText(s.store_name)}</label>`).join('')}</div><small>추천과 예산은 현재 선택한 매장 단위로 계산합니다. 여러 매장의 합산 발주 비교는 지원하지 않습니다.</small><h3>발주 제외 품목</h3><div class="checkbox-grid">${Object.values(DATA.snapshots)[0].map(i=>`<label><input type="checkbox" data-exclude="${i.ingredient_id}" ${d.constraints.excluded_ingredient_ids.includes(i.ingredient_id)?'checked':''}> ${safeText(i.ingredient_name)}</label>`).join('')}</div><p class="entry-storage-note">제외 품목은 신규 발주만 금지하며 수요와 부족 위험은 유지합니다. 긴급발주 후보는 현재 제공하지 않습니다.</p>`:`<h3>화면</h3><label class="setting-field">시작 기준일<input type="date" min="2026-09-30" max="2026-10-14" data-setting="startDate" value="${d.startDate}"><small>다음 새로고침부터 적용합니다. 기록이 있는 날짜를 선택하세요.</small></label><h3>저장</h3><p>이 브라우저에 기본 설정과 재고 기록을 저장합니다.</p><button id="exportSettings" type="button" class="button secondary">설정 내보내기</button><label class="setting-field">설정 가져오기<input id="importSettings" type="file" accept="application/json"></label><button id="resetSettings" type="button" class="text-action">기본 발주 설정으로 초기화</button>`}</div></div><div id="settingsError" role="alert" class="settings-error"></div><div class="settings-footer"><span>저장하면 다음 추천부터 적용됩니다.</span><button type="button" id="cancelSettings" class="button secondary">취소</button><button type="submit" class="button primary">저장</button></div></form>`;
 const close=()=>$('#settingsDialog').close();$('#closeSettings').onclick=$('#cancelSettings').onclick=close;
 $$('[data-settings-tab]').forEach(b=>b.onclick=()=>{try{collectSettings();settingsTab=b.dataset.settingsTab;renderSettings();}catch(e){$('#settingsError').textContent=e.message;}});
 $$('[data-preset]').forEach(b=>b.onclick=()=>{collectSettings();d.mode=b.dataset.preset;Object.assign(d.preferences,OrderPolicy.presets[d.mode]);renderSettings();});
 if($('#ownerText'))$('#ownerText').oninput=()=>{settingsOwnerDirty=true;};
 if($('#interpretOwner'))$('#interpretOwner').onclick=async()=>{const b=$('#interpretOwner');b.disabled=true;try{collectSettings();const patch=await extractRequest(d.ownerText,d.api);settingsDraft=OrderPolicy.merge(d,patch);settingsOwnerDirty=false;renderSettings();$('#ownerPreview').innerHTML=auditHTML(patch);}catch(e){$('#settingsError').textContent=e.message;}finally{b.disabled=false;}};
 if($('#exportSettings'))$('#exportSettings').onclick=()=>{collectSettings();const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(settingsDraft,null,2)],{type:'application/json'}));a.href=url;a.download='order-settings.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 if($('#resetSettings'))$('#resetSettings').onclick=()=>{settingsDraft=OrderPolicy.defaults();renderSettings();};
 if($('#importSettings'))$('#importSettings').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>65536)throw Error('설정 파일이 너무 큽니다.');const value=JSON.parse(await file.text());validateSettings(value);settingsDraft=value;renderSettings();}catch(err){$('#settingsError').textContent=err.message;}};
 $('#settingsForm').onsubmit=e=>{e.preventDefault();try{collectSettings();if(settingsOwnerDirty&&settingsDraft.ownerText.trim())throw Error('기본 성향의 문장을 먼저 ‘문장으로 기준 채우기’로 반영해주세요.');validateSettings(settingsDraft);localStorage.setItem(SETTINGS_KEY,JSON.stringify(settingsDraft));preferences=JSON.parse(JSON.stringify(settingsDraft));state.overrides={};policyCache='';close();render();toast('발주 기준을 저장했습니다.');}catch(err){$('#settingsError').textContent=err.message;}};
}
function validateSettings(p){if(p.version!==1||!OrderPolicy.presets[p.mode]||typeof p.ownerText!=='string'||p.ownerText.length>2000||typeof p.api!=='boolean')throw Error('설정 형식을 확인해주세요.');for(const [key,label,min,max,step,help,g] of policyFields){const v=p[g]?.[key];if(typeof v!=='number'||!Number.isFinite(v)||v<min||v>max||key==='delay_buffer_days'&&!Number.isInteger(v))throw Error(label+' 범위를 확인해주세요.');}if(p.preferences.shortage_weight+p.preferences.waste_weight===0)throw Error('손실 가중치를 모두 0으로 설정할 수 없습니다.');const c=p.constraints;if(!c||typeof c.allow_emergency!=='boolean')throw Error('제약 설정 오류');if(c.budget!==null&&(!['lt','le'].includes(c.budget?.operator)||!Number.isSafeInteger(c.budget.won)||c.budget.won<0||c.budget.won>1e12))throw Error('예산 형식 오류');for(const [key,max] of [['max_stockout_probability',1],['max_expected_waste_won',1e12]])if(c[key]!==null&&(typeof c[key]!=='number'||!Number.isFinite(c[key])||c[key]<0||c[key]>max))throw Error('한도 범위 오류');for(const [key,valid] of [['store_ids',DATA.stores.map(s=>s.store_id)],['excluded_ingredient_ids',Object.values(DATA.snapshots)[0].map(i=>i.ingredient_id)]])if(!(key==='store_ids'&&c[key]===null)&&(!Array.isArray(c[key])||c[key].some(x=>!valid.includes(x))||key==='store_ids'&&!c[key].length))throw Error('적용 대상 오류');if(!/^2026-(09-30|10-(0[1-9]|1[0-4]))$/.test(p.startDate))throw Error('화면 설정 범위 오류');}
function checkDraft(){if(requestDirty)throw Error('이번 주문 요청을 먼저 반영해주세요.');const policy=effectivePolicy();if(orderPatch?.audit.some(a=>a.field==='store_ids'&&a.after?.length>1))throw Error('이번 요청의 여러 매장 합산 발주는 지원하지 않습니다. 한 매장을 선택해주세요.');const quantities=Object.fromEntries(items.map(i=>[i.ingredient_id,i.orderQty]));const result=OrderPolicy.evaluate(activeSnapshot,{asOf:state.date,storeId:state.store,suppliers:DATA.suppliers,dates:forecastWindow().dates,baseIngredients:PromotionEngine.project(PROMO,state.date,state.store,forecastWindow().dates,[]).ingredients,quantities},policyProjection(),PROMO,policy);const candidate=result.candidates[0];if(!candidate.feasible)throw Error(candidate.violations.join('\n'));return candidate;}
